  SELECT *, row_number() OVER (PARTITION BY years ORDER BY roll_no) AS roster_position
  FROM supplied
), inserted_batches AS (
  INSERT INTO academic_batches (name, department, academic_years, sections, trainer_ids, status)
  SELECT years || ' CSE', 'Computer Science & Engineering', years, '["A", "B"]'::jsonb, '[2]'::jsonb, 'active'
  FROM (SELECT DISTINCT years FROM numbered) AS batches
  ON CONFLICT (name) DO NOTHING
  RETURNING academic_batch_id, academic_years AS years
)
INSERT INTO students
  (academic_batch_id, roll_no, full_name, email, batch, branch, section, cgpa, average_score, readiness_status)
SELECT
  ab.academic_batch_id,
  numbered.roll_no,
  numbered.full_name,
  numbered.roll_no || '@campus.edu',
  numbered.years || ' CSE',
  'CSE',
  CASE WHEN numbered.roster_position <= 50 THEN 'A' ELSE 'B' END,
  0.00,
  0.00,
  'NPR'::readiness_status
FROM numbered
JOIN (
  SELECT academic_batch_id, academic_years AS years FROM academic_batches
  UNION ALL
  SELECT academic_batch_id, years FROM inserted_batches
) AS ab ON ab.years = numbered.years
ON CONFLICT (roll_no) DO NOTHING;
